import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Chip,
  MenuItem,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import {
  REVIEW_CATEGORIES,
  categoryLabel,
  formatVoucherDate,
  groupByCategory,
} from './expertReviewCategories';

interface CompanySummary {
  msmeId: string;
  companyName: string;
  scope: 'required' | 'all';
  openRequired: number;
  counts: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
  open: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
}

interface ReviewRow {
  _id: string;
  date?: string;
  description?: string;
  amount?: number;
  currency?: string;
  category?: string;
  subcategory?: string;
  quantity?: number;
  unit?: string;
  vendorName?: string;
  calculationClass?: string;
  formula?: string;
  co2Emissions?: number;
  quantificationMethod?: string;
  factorId?: string;
  factor?: number | null;
  factorUnit?: string;
  recommendation?: CorrectionRecommendation | null;
}

interface CorrectionRecommendation {
  id?: string;
  title: string;
  action: string;
  category?: string;
  unit?: string;
  quantity?: number | null;
}

const classLabel = (row: ReviewRow) => {
  const method = String(row.quantificationMethod || '').toLowerCase();
  const formula = String(row.formula || '');
  if (
    method.includes('admin_emission_review')
    || formula === 'adminEmissionReview'
    || row.factorId === 'activity_classification_required'
  ) {
    return 'Needs expert review';
  }
  if (row.calculationClass === 'spend_based') return 'Spend-based';
  if (row.calculationClass === 'calculated') return 'With calculation';
  return 'Without calculation';
};

const formulaLabel = (formula?: string) => {
  if (!formula || formula === 'adminEmissionReview') return 'Waiting for a named activity';
  if (formula === 'activityQuantity * emissionFactor') return 'Quantity × emission factor';
  if (formula === '(spendAmount / unitPrice) * emissionFactor') return 'Rupees ÷ unit price × emission factor';
  if (formula === '0') return 'Result is 0 kg CO2e';
  return formula;
};

const factorNeedsActivity = (factorId?: string) => (
  !factorId
  || factorId === 'spend_generic'
  || factorId === 'activity_classification_required'
);

const ExpertCalculationReview: React.FC = () => {
  const [companies, setCompanies] = useState<CompanySummary[]>([]);
  const [msmeId, setMsmeId] = useState('');
  const [rows, setRows] = useState<ReviewRow[]>([]);
  const [note, setNote] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const token = () => localStorage.getItem('token');
  const groups = useMemo(() => groupByCategory(rows), [rows]);

  const loadCompanies = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
        headers: { Authorization: `Bearer ${token()}` },
      });
      const list = response.data?.data?.companies || [];
      setCompanies(list);
      setMsmeId((current) => current || list[0]?.msmeId || '');
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load companies waiting for review.');
    } finally {
      setLoading(false);
    }
  }, []);

  const loadRows = useCallback(async (companyId: string) => {
    if (!companyId) {
      setRows([]);
      return;
    }
    try {
      const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
        headers: { Authorization: `Bearer ${token()}` },
        params: { msmeId: companyId },
      });
      setRows(response.data?.data?.transactions || []);
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load the company review.');
    }
  }, []);

  useEffect(() => {
    void loadCompanies();
  }, [loadCompanies]);

  useEffect(() => {
    void loadRows(msmeId);
  }, [loadRows, msmeId]);

  const confirmOne = async (row: ReviewRow) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/calculation-review/confirm`),
        { note },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setNotice(`Confirmed ${row.description || 'the voucher'} in ${categoryLabel(row.category)}.`);
      setRows((current) => current.filter((item) => item._id !== row._id));
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The confirmation could not be saved.');
    } finally {
      setBusyId(null);
    }
  };

  const correctOne = async (row: ReviewRow, draft: { category: string; quantity: string; unit: string }) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/emission-review`),
        {
          category: draft.category,
          subcategory: row.subcategory || '',
          quantity: Number(draft.quantity),
          unit: draft.unit,
          note: note || 'Corrected by the expert consultant.',
        },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const saved = response.data?.data;
      const kilograms = Number(saved?.co2Emissions || 0);
      setNotice(
        `Corrected ${row.description || 'the voucher'} into ${categoryLabel(draft.category)}. `
        + `Factor ${saved?.factorId || 'applied'}. ${kilograms} kg CO2e.`
      );
      setRows((current) => current.filter((item) => item._id !== row._id));
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The correction could not be saved.');
    } finally {
      setBusyId(null);
    }
  };

  const confirmOpen = async (category?: string) => {
    if (!msmeId) return;
    setBusyId(category || 'all');
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl('/expert/calculation-review/confirm-open'),
        { msmeId, note, category: category || undefined },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setNotice(response.data?.message || 'Open rows confirmed.');
      await loadCompanies();
      await loadRows(msmeId);
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The open rows could not be confirmed.');
    } finally {
      setBusyId(null);
    }
  };

  const selected = companies.find((company) => company.msmeId === msmeId);

  return (
    <Paper sx={{ p: 2, mb: 3 }}>
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
        Calculation review by category
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Each category is a separate group. Spend-based rows, maintenance rows, and rows that need expert review carry a correction. Apply that quantity and unit, or confirm the row when the figure already matches the bill. A correction recalculates the factor and the emissions. Rupees are not multiplied by 0.001 kg CO2e per INR.
      </Typography>
      {error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}
      {notice ? <Alert severity="success" sx={{ mb: 2 }} onClose={() => setNotice(null)}>{notice}</Alert> : null}
      {loading ? <Typography variant="body2">Loading companies…</Typography> : null}
      {!loading && companies.length === 0 ? (
        <Typography variant="body2">No company ledger is waiting for a calculation review.</Typography>
      ) : null}
      {companies.length > 0 ? (
        <Box sx={{ display: 'grid', gap: 1, mb: 2 }}>
          <TextField
            select
            size="small"
            label="Company"
            value={msmeId}
            onChange={(event) => setMsmeId(event.target.value)}
          >
            {companies.map((company) => (
              <MenuItem key={company.msmeId} value={company.msmeId}>
                {`${company.companyName} · ${company.openRequired} open · ${company.counts.withoutCalculation} without calculation · ${company.counts.spendBased} spend-based`}
              </MenuItem>
            ))}
          </TextField>
          {selected ? (
            <Typography variant="body2" color="text.secondary">
              {selected.scope === 'all'
                ? 'This company also asked for review of transactions that already have a calculation.'
                : 'Required review covers rows without a calculation and spend-based rows.'}
            </Typography>
          ) : null}
          <TextField
            size="small"
            label="Note for this review"
            value={note}
            onChange={(event) => setNote(event.target.value)}
          />
          <Button variant="outlined" disabled={!msmeId || busyId === 'all' || rows.length === 0} onClick={() => { void confirmOpen(); }}>
            {busyId === 'all' ? 'Confirming' : 'Confirm all open rows'}
          </Button>
        </Box>
      ) : null}
      {groups.length > 0 ? (
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
          {groups.map((group) => (
            <Chip key={group.key} label={`${group.label} · ${group.rows.length}`} color="primary" variant="outlined" />
          ))}
        </Box>
      ) : null}
      {groups.map((group) => (
        <Accordion key={group.key} defaultExpanded disableGutters>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
              <Typography sx={{ fontWeight: 700 }}>{group.label}</Typography>
              <Chip size="small" label={`${group.rows.length} open`} />
            </Box>
          </AccordionSummary>
          <AccordionDetails>
            <Button
              size="small"
              variant="outlined"
              sx={{ mb: 1 }}
              disabled={busyId === group.key}
              onClick={() => { void confirmOpen(group.key); }}
            >
              {busyId === group.key ? 'Confirming' : `Confirm ${group.label}`}
            </Button>
            {group.rows.map((row) => (
              <ReviewRowEditor
                key={row._id}
                row={row}
                busy={busyId === row._id}
                onConfirm={() => { void confirmOne(row); }}
                onCorrect={(draft) => { void correctOne(row, draft); }}
              />
            ))}
          </AccordionDetails>
        </Accordion>
      ))}
      {!loading && msmeId && rows.length === 0 ? (
        <Typography variant="body2">No open rows for this company.</Typography>
      ) : null}
    </Paper>
  );
};

const ReviewRowEditor: React.FC<{
  row: ReviewRow;
  busy: boolean;
  onConfirm: () => void;
  onCorrect: (draft: { category: string; quantity: string; unit: string }) => void;
}> = ({ row, busy, onConfirm, onCorrect }) => {
  const suggested = row.recommendation;
  const [category, setCategory] = useState(suggested?.category || row.category || 'other');
  const [quantity, setQuantity] = useState(
    suggested
      ? (suggested.quantity != null ? String(suggested.quantity) : '')
      : (row.quantity != null ? String(row.quantity) : '')
  );
  const [unit, setUnit] = useState(suggested ? (suggested.unit || '') : (row.unit || ''));
  const needsActivity = factorNeedsActivity(row.factorId);
  const factorLine = needsActivity
    ? 'No activity factor yet. Emissions stay at 0 kg CO2e until you name the activity.'
    : `Factor ${row.factorId}${row.factor != null ? ` · ${row.factor} ${row.factorUnit || ''}`.trim() : ''}`;
  const when = formatVoucherDate(row.date);

  return (
    <Box sx={{ borderTop: 1, borderColor: 'divider', py: 2 }}>
      <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap', mb: 0.5 }}>
        <Typography variant="subtitle2">{row.description || 'Untitled voucher'}</Typography>
        <Chip size="small" label={classLabel(row)} />
      </Box>
      <Typography variant="body2" color="text.secondary">
        {[
          when,
          row.vendorName,
          row.amount != null ? `${row.amount} ${row.currency || 'INR'}` : 'No amount',
          row.subcategory ? `Subcategory ${row.subcategory}` : '',
        ].filter(Boolean).join(' · ')}
      </Typography>
      <Typography variant="body2" sx={{ mt: 0.5 }}>
        {`${factorLine} · ${formulaLabel(row.formula)} · ${Number(row.co2Emissions || 0)} kg CO2e`}
      </Typography>
      {suggested ? (
        <Alert severity="info" sx={{ mt: 1 }}>
          <Typography variant="subtitle2">{suggested.title}</Typography>
          <Typography variant="body2">{suggested.action}</Typography>
        </Alert>
      ) : null}
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1.4fr 0.7fr 0.7fr auto auto' }, gap: 1, mt: 1 }}>
        <TextField select size="small" label="Category" value={REVIEW_CATEGORIES.includes(category as typeof REVIEW_CATEGORIES[number]) ? category : 'other'} onChange={(event) => setCategory(event.target.value)}>
          {REVIEW_CATEGORIES.map((item) => <MenuItem key={item} value={item}>{categoryLabel(item)}</MenuItem>)}
        </TextField>
        <TextField size="small" label="Quantity" value={quantity} onChange={(event) => setQuantity(event.target.value)} />
        <TextField size="small" label="Unit" value={unit} placeholder="kg, L, kWh" onChange={(event) => setUnit(event.target.value)} />
        <Button variant="outlined" disabled={busy} onClick={onConfirm}>Confirm</Button>
        <Button
          variant="contained"
          disabled={busy || quantity === '' || !unit}
          onClick={() => onCorrect({ category, quantity, unit })}
        >
          Correct factor
        </Button>
      </Box>
    </Box>
  );
};

export default ExpertCalculationReview;
