import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Alert,
    Box,
    Button,
    Chip,
    MenuItem,
    Paper,
    TextField,
    Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import {
    REVIEW_CATEGORIES,
    categoryLabel,
    formatVoucherDate,
    groupByCategory,
} from './expertReviewCategories';

interface ReviewTransaction {
    _id: string;
    date?: string;
    description?: string;
    amount?: number;
    currency?: string;
    category?: string;
    subcategory?: string;
    quantity?: number;
    unit?: string;
    vendor?: { name?: string };
    msmeId?: { companyName?: string } | string;
    carbonFootprint?: {
        co2Emissions?: number;
        calculationRecord?: { formula?: string };
        factorLineage?: { id?: string; factor?: number; unit?: string };
    };
    recommendation?: CorrectionRecommendation | null;
}

interface CorrectionRecommendation {
    title: string;
    action: string;
    category?: string;
    unit?: string;
    quantity?: number | null;
}

interface Draft {
    category: string;
    subcategory: string;
    quantity: string;
    unit: string;
    note: string;
}

const companyName = (row: ReviewTransaction) => {
    if (row.msmeId && typeof row.msmeId === 'object') return row.msmeId.companyName || '';
    return '';
};

const emptyDraft = (row: ReviewTransaction): Draft => {
    const suggested = row.recommendation;
    return {
        category: suggested?.category || row.category || 'other',
        subcategory: row.subcategory || '',
        quantity: suggested
            ? (suggested.quantity != null ? String(suggested.quantity) : '')
            : (row.quantity != null ? String(row.quantity) : ''),
        unit: suggested ? (suggested.unit || '') : (row.unit || ''),
        note: '',
    };
};

const factorLine = (row: ReviewTransaction) => {
    const factorId = row.carbonFootprint?.factorLineage?.id;
    if (!factorId || factorId === 'spend_generic' || factorId === 'activity_classification_required') {
        return 'No activity factor. Inventory 0 kg CO2e. The 0.001 kg CO2e per INR residual is not applied.';
    }
    const factor = row.carbonFootprint?.factorLineage?.factor;
    const unit = row.carbonFootprint?.factorLineage?.unit || '';
    return `Current factor ${factorId}${factor != null ? ` · ${factor} ${unit}` : ''} · ${Number(row.carbonFootprint?.co2Emissions || 0)} kg CO2e`;
};

const ExpertEmissionReview: React.FC = () => {
    const [rows, setRows] = useState<ReviewTransaction[]>([]);
    const [drafts, setDrafts] = useState<Record<string, Draft>>({});
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [notice, setNotice] = useState<string | null>(null);
    const [savingId, setSavingId] = useState<string | null>(null);
    const groups = useMemo(() => groupByCategory(rows), [rows]);

    const load = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const response = await axios.get(buildApiUrl('/expert/emission-review'), {
                headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
                params: { limit: 200 },
            });
            const transactions = response.data?.data?.transactions || [];
            setRows(transactions);
            setDrafts((current) => {
                const next = { ...current };
                transactions.forEach((row: ReviewTransaction) => {
                    if (!next[row._id]) next[row._id] = emptyDraft(row);
                });
                return next;
            });
        } catch (loadError: any) {
            setError(loadError?.response?.data?.message || 'Failed to load transactions that need an activity classification.');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        load();
    }, [load]);

    const updateDraft = (id: string, patch: Partial<Draft>) => {
        setDrafts((current) => ({
            ...current,
            [id]: { ...(current[id] || emptyDraft({ _id: id })), ...patch },
        }));
    };

    const save = async (row: ReviewTransaction) => {
        const draft = drafts[row._id] || emptyDraft(row);
        setSavingId(row._id);
        setError(null);
        setNotice(null);
        try {
            const response = await axios.post(
                buildApiUrl(`/expert/transactions/${row._id}/emission-review`),
                {
                    category: draft.category,
                    subcategory: draft.subcategory,
                    quantity: Number(draft.quantity),
                    unit: draft.unit,
                    note: draft.note,
                },
                { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
            );
            const saved = response.data?.data;
            setNotice(
                `Calculated and confirmed ${row.description || 'the voucher'} in ${categoryLabel(draft.category)}. `
                + `Factor ${saved?.factorId || 'applied'}. ${Number(saved?.co2Emissions || 0)} kg CO2e.`
            );
            setRows((current) => current.filter((item) => item._id !== row._id));
        } catch (saveError: any) {
            setError(saveError?.response?.data?.message || 'The classification could not be saved.');
        } finally {
            setSavingId(null);
        }
    };

    return (
        <Paper sx={{ p: 2, mb: 3 }}>
            <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
                Activity classification by category
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                These vouchers need expert review. A spend-based, maintenance, or unclassified row shows the correction to apply. Enter that quantity and unit. The inventory then applies the stored factor, recalculates the kilograms, and records the correction.
            </Typography>
            {error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}
            {notice ? <Alert severity="success" sx={{ mb: 2 }} onClose={() => setNotice(null)}>{notice}</Alert> : null}
            {loading ? <Typography variant="body2">Loading transactions…</Typography> : null}
            {!loading && rows.length === 0 ? (
                <Typography variant="body2">No transactions are waiting for an activity classification.</Typography>
            ) : null}
            {groups.length > 0 ? (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                    {groups.map((group) => (
                        <Chip key={group.key} label={`${group.label} · ${group.rows.length}`} color="secondary" variant="outlined" />
                    ))}
                </Box>
            ) : null}
            {groups.map((group) => (
                <Accordion key={group.key} defaultExpanded disableGutters>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                            <Typography sx={{ fontWeight: 700 }}>{group.label}</Typography>
                            <Chip size="small" label={`${group.rows.length} to classify`} />
                        </Box>
                    </AccordionSummary>
                    <AccordionDetails>
                        {group.rows.map((row) => {
                            const draft = drafts[row._id] || emptyDraft(row);
                            const when = formatVoucherDate(row.date);
                            return (
                                <Box key={row._id} sx={{ borderTop: 1, borderColor: 'divider', py: 2 }}>
                                    <Typography variant="subtitle2">
                                        {row.description || 'Untitled voucher'}
                                        {companyName(row) ? ` · ${companyName(row)}` : ''}
                                    </Typography>
                                    <Typography variant="body2" color="text.secondary">
                                        {[
                                            when,
                                            row.vendor?.name,
                                            row.amount != null ? `${row.amount} ${row.currency || 'INR'}` : 'No amount',
                                            `Category ${categoryLabel(row.category)}`,
                                        ].filter(Boolean).join(' · ')}
                                    </Typography>
                                    <Typography variant="body2" sx={{ mt: 0.5, mb: 1 }}>
                                        {factorLine(row)}
                                    </Typography>
                                    {row.recommendation ? (
                                        <Alert severity="info" sx={{ mb: 1 }}>
                                            <Typography variant="subtitle2">{row.recommendation.title}</Typography>
                                            <Typography variant="body2">{row.recommendation.action}</Typography>
                                        </Alert>
                                    ) : null}
                                    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1.3fr 1fr 0.7fr 0.7fr 1.4fr auto' }, gap: 1, alignItems: 'center' }}>
                                        <TextField
                                            select
                                            size="small"
                                            label="Category"
                                            value={REVIEW_CATEGORIES.includes(draft.category as typeof REVIEW_CATEGORIES[number]) ? draft.category : 'other'}
                                            onChange={(event) => updateDraft(row._id, { category: event.target.value })}
                                        >
                                            {REVIEW_CATEGORIES.map((category) => (
                                                <MenuItem key={category} value={category}>{categoryLabel(category)}</MenuItem>
                                            ))}
                                        </TextField>
                                        <TextField
                                            size="small"
                                            label="Subcategory"
                                            value={draft.subcategory}
                                            onChange={(event) => updateDraft(row._id, { subcategory: event.target.value })}
                                        />
                                        <TextField
                                            size="small"
                                            label="Quantity"
                                            value={draft.quantity}
                                            onChange={(event) => updateDraft(row._id, { quantity: event.target.value })}
                                            inputProps={{ inputMode: 'decimal' }}
                                        />
                                        <TextField
                                            size="small"
                                            label="Unit"
                                            value={draft.unit}
                                            placeholder="kg, L, kWh"
                                            onChange={(event) => updateDraft(row._id, { unit: event.target.value })}
                                        />
                                        <TextField
                                            size="small"
                                            label="What this purchase is"
                                            value={draft.note}
                                            onChange={(event) => updateDraft(row._id, { note: event.target.value })}
                                        />
                                        <Button
                                            variant="contained"
                                            disabled={savingId === row._id || draft.quantity === '' || !draft.unit}
                                            onClick={() => save(row)}
                                        >
                                            {savingId === row._id ? 'Saving' : 'Calculate and confirm'}
                                        </Button>
                                    </Box>
                                </Box>
                            );
                        })}
                    </AccordionDetails>
                </Accordion>
            ))}
        </Paper>
    );
};

export default ExpertEmissionReview;
