import React from 'react';
import ExpertPortalLayout from './ExpertPortalLayout';
import ExpertCalculationReview from './ExpertCalculationReview';
import ExpertEmissionReview from './ExpertEmissionReview';

const ExpertDashboard: React.FC = () => (
  <ExpertPortalLayout
    title="Consultant review"
    subtitle="Transactions are grouped by category. Spend-based rows, maintenance rows, and rows that need expert review show the correction to apply. Confirm a row when that figure already matches the bill. The company generates its report after the open rows are settled."
  >
    <ExpertCalculationReview />
    <ExpertEmissionReview />
  </ExpertPortalLayout>
);

export default ExpertDashboard;
